import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Milestones","description":"","frontmatter":{},"headers":[],"relativePath":"project/milestones.md","filePath":"project/milestones.md"}'),i={name:"project/milestones.md"};function n(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h1><p>This project has been built, submitted, and extended across several distinct venues, not as one linear submission. This page is the single timeline: what each stage actually added to the architecture, what came of it, and which paths are still open or under way. Each milestone links to a full write-up where one exists.</p><h2 id="_1-uzh-blockchain-—-deep-dive-into-blockchain-2026-17–23-july-2026" tabindex="-1">1. UZH Blockchain — Deep Dive into Blockchain 2026 (17–23 July 2026) <a class="header-anchor" href="#_1-uzh-blockchain-—-deep-dive-into-blockchain-2026-17–23-july-2026" aria-label="Permalink to &quot;1. UZH Blockchain — Deep Dive into Blockchain 2026 (17–23 July 2026)&quot;">​</a></h2><p>The origin. Built from scratch for the University of Zurich&#39;s DDiB 2026 summer school: the Hedera trust layer (compliance, quote, and routing anchors via HCS), corridor routing across five settlement chains, a full web + mobile app, a real database, a real test suite, and the initial documentation site. Full phase-by-phase detail: <a href="./uzh-blockchain.html">UZH Blockchain</a>.</p><p><strong>Outcome:</strong> completed submission, 23 July hand-in.</p><h2 id="_2-ethglobal-lisbon-2026-24–26-july-2026" tabindex="-1">2. ETHGlobal Lisbon 2026 (24–26 July 2026) <a class="header-anchor" href="#_2-ethglobal-lisbon-2026-24–26-july-2026" aria-label="Permalink to &quot;2. ETHGlobal Lisbon 2026 (24–26 July 2026)&quot;">​</a></h2><p>Independently extended past the UZH submission for ETHGlobal Lisbon, Continuity Track. Added the HSS-gated, 2-of-2 threshold-key completion anchor, a dedicated completion topic, the How It Works walkthrough page, and the SaucerSwap liquidity source. Full detail: <a href="./ethglobal-lisbon.html">ETHGlobal Lisbon 2026</a>.</p><p><strong>Outcome:</strong> won the <strong>Autonomous On-Chain Automation Platform</strong> partner prize (Hedera track).</p><h2 id="_3-becoming-a-collection-the-site-split-and-onchain-oversight-26–28-july-2026" tabindex="-1">3. Becoming a collection: the site split, and OnChain Oversight (26–28 July 2026) <a class="header-anchor" href="#_3-becoming-a-collection-the-site-split-and-onchain-oversight-26–28-july-2026" aria-label="Permalink to &quot;3. Becoming a collection: the site split, and OnChain Oversight (26–28 July 2026)&quot;">​</a></h2><p>Two things happened together here, worth documenting since neither is covered by the two pages above.</p><p><strong>The site restructured into a collection.</strong> The root route (<code>/</code>) is now a hub introducing the collection, F2F Cross-Border moved to its own route (<code>/cross-border</code>), and a regulator-facing section (public Mirror Node observability, at retail and institutional scale) was added to the How It Works page. Sitewide typeface changed to Inter.</p><p><strong>OnChain Oversight, a sister project, was conceived.</strong> Built on the same trust-layer philosophy, public data, independently verifiable, never a black box, but for a different audience: an autonomous agent that continuously watches public on-chain activity (Hedera and Ethereum) and surfaces prioritised, source-linked findings to a named human regulator, rather than serving transfer senders directly. It reuses F2F&#39;s own HSS completion-anchor and threshold-account infrastructure as its first real, working proof case, see <a href="./../legal/regulator-oversight.html">the regulator-oversight case</a> for the shared architectural reasoning.</p><p><strong>Outcome:</strong> ongoing; the collection hub and regulator-oversight section are live.</p><h2 id="_4-cambridge-c-dir-agentic-regulator-hackathon-—-preliminary-round-submitted-28-july-2026" tabindex="-1">4. Cambridge C:&gt;DIR &#39;Agentic Regulator&#39; Hackathon — Preliminary Round (submitted 28 July 2026) <a class="header-anchor" href="#_4-cambridge-c-dir-agentic-regulator-hackathon-—-preliminary-round-submitted-28-july-2026" aria-label="Permalink to &quot;4. Cambridge C:\\&gt;DIR &#39;Agentic Regulator&#39; Hackathon — Preliminary Round (submitted 28 July 2026)&quot;">​</a></h2><p>The first formal submission for <strong>OnChain Oversight</strong> specifically, not F2F itself, under the team name &quot;F2F OnChain Oversight&quot;, targeting the Decentralised Market Infrastructure and Agentic Payments Oversight problem spaces. A hierarchical planner-worker agent design (retrieval, analysis, and verifier/critic agents) built directly on F2F&#39;s proven HSS mechanism as the Hedera-side proof case.</p><p><strong>Outcome:</strong> pending, Preliminary Round results expected mid-August 2026.</p><h2 id="open-or-potential-future-paths" tabindex="-1">Open or potential future paths <a class="header-anchor" href="#open-or-potential-future-paths" aria-label="Permalink to &quot;Open or potential future paths&quot;">​</a></h2><p>Tracked here as they&#39;re decided, rather than duplicated across pages:</p><table tabindex="0"><thead><tr><th>Path</th><th>Status</th></tr></thead><tbody><tr><td>Cambridge C:&gt;DIR Final Round</td><td>Pending Preliminary Round result</td></tr><tr><td>Ethereum Foundation Ecosystem Support Program (ESP)</td><td>Under consideration, for OnChain Oversight, independent of the Cambridge result</td></tr><tr><td>ETHGlobal Online / other future ETHGlobal events</td><td>Under consideration</td></tr></tbody></table><h2 id="what-each-milestone-actually-changed-at-a-glance" tabindex="-1">What each milestone actually changed, at a glance <a class="header-anchor" href="#what-each-milestone-actually-changed-at-a-glance" aria-label="Permalink to &quot;What each milestone actually changed, at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Added to the architecture</th></tr></thead><tbody><tr><td>UZH Blockchain</td><td>HCS trust layer (3 anchor types), corridor routing, full app, real DB, real tests</td></tr><tr><td>ETHGlobal Lisbon 2026</td><td>HSS completion anchor, 2-of-2 threshold account, dedicated completion topic, SaucerSwap liquidity</td></tr><tr><td>Site split + OnChain Oversight</td><td>Collection hub, <code>/cross-border</code> split, regulator-oversight section, sister project defined</td></tr><tr><td>Cambridge C:&gt;DIR (submitted)</td><td>Formal agentic architecture proposal (retrieval/analysis/verifier agents) for OnChain Oversight</td></tr></tbody></table>',21)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
